import{_ as r,c as e,o,a1 as n}from"./chunks/framework.C3Hmo1as.js";const F=JSON.parse('{"title":"透视 Transformer","description":null,"frontmatter":{"title":"透视 Transformer","description":null,"date":"2026-11-02T00:00:00.000Z","tags":["Transformer"]},"headers":[],"relativePath":"ai/transformer.md","filePath":"ai/transformer.md"}'),a={name:"ai/transformer.md"};function s(i,t,l,d,g,p){return o(),e("div",null,[...t[0]||(t[0]=[n('<p>在了解大语言模型（LLM）时，很多人会产生一个直觉上的困惑：既然模型在发布时，它几十上百亿的参数权重都已经固定死了，那它究竟是如何做到既能“理解”多变的上下文，又能“记忆”海量的知识的？</p><p>答案隐藏在 Transformer 架构的两个核心组件的分工里：<strong>Attention（注意力机制）</strong>和 <strong>Feedforward（前馈神经网络，简称 FFN）</strong>。它们就像一台精密机器中两种功能迥异的齿轮，交替运转，赋予了模型强大的能力。</p><h2 id="attention-动态的上下文路由器" tabindex="-1">Attention：动态的上下文路由器 <a class="header-anchor" href="#attention-动态的上下文路由器" aria-label="Permalink to &quot;Attention：动态的上下文路由器&quot;">​</a></h2><p>尽管 Attention 层的参数权重是固定的，但它的<strong>计算过程是动态的</strong>。</p><p>它的核心工作是“左右环顾”。当模型读取一个句子时，Attention 机制不会孤立地看待某个词，而是计算当前词与句子中其他所有词的关联权重。</p><ul><li><strong>消解歧义</strong>：在“苹果公司”和“吃苹果”中，Attention 会敏锐地捕捉到“公司”或“吃”的语境，从而将“苹果”这个词引导向完全不同的向量表示。</li><li><strong>逻辑揉捏</strong>：它本身不负责记忆具体的实体知识。它的参数经过训练，主要是为了掌握语言的语法、逻辑和代词指代，将整个句子的上下文信息完美地浓缩、融合到当前词的向量中。</li></ul><h2 id="feedforward-静态的键值对知识库" tabindex="-1">Feedforward：静态的键值对知识库 <a class="header-anchor" href="#feedforward-静态的键值对知识库" aria-label="Permalink to &quot;Feedforward：静态的键值对知识库&quot;">​</a></h2><p>如果说 Attention 是在看外部环境，那 Feedforward 就是在“闭门造车”。在 Transformer 中，FFN 占据了大约三分之二的参数量。</p><p>当 Attention 把融合了上下文信息的向量交给当前词后，FFN 开始独立处理这个词，不再理会句子中的其他部分。近年来的学术研究证实，FFN 实际上扮演着一个巨大的 <strong>Key-Value（键-值）记忆网络</strong>的角色：</p><ul><li><strong>Key（键）</strong>：FFN 的第一层（升维操作）负责模式匹配。它用来识别输入向量中是否包含了某种特定的概念（例如“法国+首都”的复合概念）。</li><li><strong>Value（值）</strong>：FFN 的第二层（降维操作）负责知识提取。一旦第一层匹配成功，第二层就会将对应的知识特征（例如“巴黎”）提取出来并叠加到输出中。</li></ul><h2 id="架构之美-多层-千层饼-协同" tabindex="-1">架构之美：多层“千层饼”协同 <a class="header-anchor" href="#架构之美-多层-千层饼-协同" aria-label="Permalink to &quot;架构之美：多层“千层饼”协同&quot;">​</a></h2><p>大模型并非只有“一大块 Attention”接着“一大块 FFN”。经典的 Transformer 架构是由几十个基础的 <strong>Transformer Block（块）</strong> 堆叠而成的“千层饼”。</p><p>每个 Block 内部都包含一个 Attention 层和一个 FFN 层。模型处理信息是一个极度深度的流水线过程： <code>输入 -&gt; [层1 Attention -&gt; 层1 FFN] -&gt; [层2 Attention -&gt; 层2 FFN] -&gt; ... -&gt; [顶层]</code></p><ul><li><strong>在浅层</strong>：Attention 可能只是做基础的词法组合，FFN 提取基础的词性。</li><li><strong>在深层</strong>：Attention 开始处理极其复杂的长距离逻辑连结，而 FFN 则被触发提取深度的实体世界知识。</li></ul><h2 id="生成机制-自回归-autoregressive" tabindex="-1">生成机制：自回归（Autoregressive） <a class="header-anchor" href="#生成机制-自回归-autoregressive" aria-label="Permalink to &quot;生成机制：自回归（Autoregressive）&quot;">​</a></h2><p>当输入文本穿过所有的“千层饼”到达最顶层后，模型会得到一个最终的向量表示。经过概率计算，模型会输出得分最高的下一个字。</p><p>随后，模型会把 <strong>“原输入 + 新生成的字”</strong> 拼接在一起，作为一个全新的完整输入，重新送回第一层，把上述所有的流程再走一遍，去预测下一个字。这种“一个字一个字往外蹦”的机制，在技术上被称为<strong>自回归</strong>。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>固化的模型参数并不意味着死板。在 Transformer 中，Attention 提供了敏锐的“阅读理解能力”，FFN 构筑了庞大的“维基百科词条”。两者在几十层的空间里交替协作，再配合自回归的生成方式，最终造就了我们所看到的人工智能奇迹。</p>',19)])])}const u=r(a,[["render",s]]);export{F as __pageData,u as default};
